import React, { useState, useRef, useEffect } from 'react';
import styles from './chat-react.module.css';
import { callApi } from '../api/client';
import { useLocation } from 'react-router-dom';

export default function Rag() {
  const { search } = useLocation();
  const [queryInput, setQueryInput] = useState('');
  const [messages, setMessages] = useState([]); // { sender:'user'|'bot', text }
  const containerRef = useRef(null);
  const inputRef = useRef(null);

  // On mount: fetch initial query if present
  useEffect(() => {
    const params = new URLSearchParams(search);
    const q = params.get('query')?.trim();
    if (q) {
      setQueryInput(q);
      setMessages([{ sender: 'user', text: q }]);
      _fetchAnswer(q);
    }
  }, [search]);

  // Auto-scroll on new messages
  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages]);

  const _fetchAnswer = async (prompt) => {
    try {
      const { answer } = await callApi('rag', 'POST', { query: prompt });
      setMessages(m => [...m, { sender: 'bot', text: answer }]);
    } catch (err) {
      console.error(err);
      setMessages(m => [...m, { sender: 'bot', text: 'Error fetching response.' }]);
    }
  };

  const submitQuery = async (e) => {
    if (e) e.preventDefault();
    const prompt = queryInput.trim();
    if (!prompt) return;

    setMessages(m => [...m, { sender: 'user', text: prompt }]);
    setQueryInput('');
    inputRef.current?.focus();
    _fetchAnswer(prompt);
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      submitQuery();
    }
  };

  return (
    <div className={styles.autoML}>
      <div className={styles.container}>
        {/* Chat History */}
        <div className={styles.chatContainer} ref={containerRef}>
          {messages.map((m, i) => (
            <div
              key={i}
              className={`${styles.chatBubble} ${
                m.sender === 'user' ? styles.userBubble : styles.botBubble
              }`}
            >
              {m.text}
            </div>
          ))}
        </div>

        {/* Input Area */}
        <form onSubmit={submitQuery} className={styles.inputArea}>
          <div className={styles.inputWrapper}>
            <input
              type="text"
              ref={inputRef}
              className={styles.inputField}
              placeholder="Type your message..."
              value={queryInput}
              onChange={e => setQueryInput(e.target.value)}
              onKeyDown={handleKeyDown}
              autoComplete="off"
            />
            <button
              type="button"
              onClick={submitQuery}
              className={styles.iconButton}
              disabled={!queryInput.trim()}
              title="Send"
            >
              ➤
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
